// === Tab: mySketch ===
let myShader;

let vs =
"precision mediump float;" +
"attribute vec3 aPosition;" +
"void main(void){" +
"  gl_Position = vec4(aPosition, 1.0);" +
"}";

let fs =
"precision mediump float;" +
"uniform vec2 u_resolution;" +
"uniform float u_time;" +
"const float pi = 3.14159;" +
// hsb to rgb.
"vec3 getRGB(float h){" +
"  vec3 rgb = clamp(abs(mod(h * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);" +
"  return rgb * rgb * (3.0 - 2.0 * rgb);" +
"}" +
// rotate.
"void rotate(inout vec2 p, float phase){" +
"  float t = phase * 2.0 * pi;" +
"  p *= mat2(cos(t), sin(t), -sin(t), cos(t));" +
"}" +
// square.
"bool drawSquare(vec2 p, float size, float phase){" +
"  rotate(p, phase);" +
"  return max(abs(p.x), abs(p.y)) < size;" +
"}" +
// cross.
"bool drawCross(vec2 p, vec2 size, float phase){" +
"  rotate(p, phase);" +
"  return (abs(p.x) < size.x && abs(p.y) < size.y) || (abs(p.x) < size.y && abs(p.y) < size.x);" +
"}" +
// phase:0.0～1.0は2.0 * piを掛けて位相のずれに使う
"bool drawStar(vec2 p, vec2 size, float phase){" +
"  float t = mod((atan(p.y, p.x) + 2.0 * pi * (1.0 + phase)) * 2.5 / pi, 5.0);" +
"  float f = min(fract(t), 1.0 - fract(t));" +
"  float lmd = size.y * sin(0.2 * pi) / (size.x - size.y * cos(0.2 * pi));" +
"  p = vec2(cos(f * 0.4 * pi), sin(f * 0.4 * pi)) * length(p);" +
"  return p.y < lmd * (size.x - p.x);" +
"}" +
// moon.
"bool drawMoon(vec2 p, float r, float phase){" +
"  rotate(p, phase);" +
"  return length(p) < r && length(p - vec2(r * 0.6, 0.0)) > r * 0.75;" +
"}" +
// まとめ
"bool drawShape(vec2 p, float phase, float kind){" +
"  if(kind == 0.0){ return drawStar(p, vec2(1.5, 0.7), phase); }" +
"  if(kind == 1.0){ return drawMoon(p, 1.0, phase); }" +
"  if(kind == 2.0){ return drawSquare(p, 0.8, phase); }" +
"  return drawCross(p, vec2(1.2, 0.3), mod(u_time * 0.75, 1.0)); " +
"}" +
"void setP(inout vec2 p, float t){" +
"  if(t < 1.0){ p *= 0.5; return; }" +
"  for(float i = 1.0; i <= 4.0; i += 1.0){" +
"    if(t - 1.0 < i){ break; }" +
"    p = 2.0 * (abs(p) - 2.5);" +
"  }" +
"  p = 0.8 * (abs(p) - 2.5);" +
"}" +
"void main(void){" +
"  vec2 p = (gl_FragCoord.xy - u_resolution) / min(u_resolution.x, u_resolution.y);" +
"  vec3 col = vec3(0.3 * (p.y + 1.0));" +
"  p *= 5.0;" +
"  setP(p, mod(u_time, 6.0));" +
"  float phase = mod(u_time * 0.75, 1.0);" +
"  if(drawShape(p, phase, floor(mod(u_time, 24.0) / 6.0))){ col = getRGB(floor(mod(u_time, 6.0)) / 6.0); }" +
"  gl_FragColor = vec4(col, 1.0);" +
"}";

function setup(){
  createCanvas(1112, 834, WEBGL);
  myShader = createShader(vs, fs);
  shader(myShader);
	(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) = width / 2;
	(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) = height / 2;
}

function draw(){
  myShader.setUniform("u_resolution", [width, height]);
  myShader.setUniform("u_time", millis() / (100 + width - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))) );
  quad(-1, -1, -1, 1, 1, 1, 1, -1);
}

function keyPressed() {save('pix.jpg'); };

